    "Fotografier oder importier deine Rechnungen – ich lese Kunde, Betrag, Nummer und Zahlungsziel selbst. Kommt das Geld, hake ich sie ab – und wenn jemand nicht zahlt, schreib ich dir eine freundliche Erinnerung.",
