    "صوّر رسالة من عدة صفحات دفعة واحدة أو اختر عدة صور من المعرض. أرسل الصور وملفات PDF من واتساب أو البريد إليّ مباشرة عبر „مشاركة ← Finanz MAMI“.",
    "Fotografiază o scrisoare cu mai multe pagini dintr-o dată sau alege mai multe poze din galerie. Trimite-mi poze și PDF-uri din WhatsApp sau e-mail cu „Partajează → Finanz MAMI”.",
