    "Bist du angestellt und selbstständig? Auf „Beruf“ stehen jetzt „Mein Job“ und „Mein Geschäft“ getrennt. Am Handy liegt das Geschäft hinter dem Job – nach unten wischen oder antippen, dann wechseln die Kacheln.",
